package local.m13.home;
import android.app.Activity;
import android.content.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.concurrent.*;

public class CastActivity extends Activity {
 private final Handler ui=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status,detail;private boolean destroyed,starting,restart;
 private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 private GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));return d;}
 private void button(LinearLayout row,String label,final Runnable r){final TextView t=text(label,14,0xffbdc3cc);t.setPadding(dp(22),dp(12),dp(22),dp(12));t.setGravity(Gravity.CENTER);t.setBackground(bg(0xff234c7c));t.setFocusable(true);t.setClickable(true);t.setOnFocusChangeListener(new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean f){t.setBackground(f?BlueRedTheme.focus(dp(12)):bg(0xff234c7c));t.setTextColor(f?BlueRedTheme.DARK:BlueRedTheme.TEXT);}});t.setOnClickListener(new View.OnClickListener(){public void onClick(View v){r.run();}});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.rightMargin=dp(12);row.addView(t,p);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);ScreenPolicy.applyWindow(this);HomePolicy.applyIfOwner(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(68),dp(34),dp(68),dp(30));root.setBackground(BlueRedTheme.background(0));root.addView(text("轻桌面  /  投屏",15,BlueRedTheme.FAINT),new LinearLayout.LayoutParams(-1,dp(48)));LinearLayout body=new LinearLayout(this);body.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(this);icon.setImageDrawable(new MinimalIcon("cast",BlueRedTheme.BLUE));LinearLayout.LayoutParams iconP=new LinearLayout.LayoutParams(dp(155),dp(155));iconP.rightMargin=dp(80);body.addView(icon,iconP);LinearLayout content=new LinearLayout(this);content.setOrientation(1);TextView heading=new BlueRedTheme.BrandText(this);heading.setText(CastServer.NAME);heading.setTextSize(40);heading.setTextColor(BlueRedTheme.TEXT);heading.setGravity(Gravity.CENTER_VERTICAL);heading.setTypeface(Typeface.create("sans-serif-light",0));content.addView(heading,new LinearLayout.LayoutParams(-1,dp(76)));status=text("正在开启接收…",15,BlueRedTheme.BLUE);content.addView(status,new LinearLayout.LayoutParams(-1,dp(42)));content.addView(text("01   手机和盒子连接同一 Wi-Fi",18,BlueRedTheme.TEXT),new LinearLayout.LayoutParams(-1,dp(54)));content.addView(text("02   打开视频 App，点击 TV 投屏图标",18,BlueRedTheme.TEXT),new LinearLayout.LayoutParams(-1,dp(54)));content.addView(text("03   选择「轻桌面 M13」",18,BlueRedTheme.TEXT),new LinearLayout.LayoutParams(-1,dp(54)));content.addView(text("支持兼容 DLNA 的视频投屏；手机桌面镜像需另行适配。",12,BlueRedTheme.MUTED),new LinearLayout.LayoutParams(-1,dp(46)));detail=text("",12,BlueRedTheme.FAINT);content.addView(detail,new LinearLayout.LayoutParams(-1,dp(28)));body.addView(content,new LinearLayout.LayoutParams(0,-2,1));root.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);button(controls,"回到首页",new Runnable(){public void run(){finish();}});button(controls,"重新开启",new Runnable(){public void run(){restart=true;start();}});button(controls,"网络设置",new Runnable(){public void run(){try{startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}});button(controls,"关闭接收",new Runnable(){public void run(){CastServer.stop();status.setText("接收已关闭");detail.setText("需要时可选择“重新开启”");}});root.addView(controls);root.addView(text("接收开启后可返回首页。关闭接收后，手机将无法发现此设备。",11,BlueRedTheme.FAINT),new LinearLayout.LayoutParams(-1,dp(40)));setContentView(root);TvUi.inset(this);start();ui.post(tick);}
 private void start(){if(starting)return;starting=true;status.setText("正在开启接收…");worker.submit(new Runnable(){public void run(){try{if(restart){CastServer.stop();restart=false;}final CastServer server=CastServer.start(CastActivity.this);ui.post(new Runnable(){public void run(){if(!destroyed){starting=false;status.setText("接收已开启 · 等待手机连接");detail.setText(server.ip);}}});}catch(final Exception e){ui.post(new Runnable(){public void run(){if(!destroyed){starting=false;status.setText("接收未开启，请检查网络");detail.setText(e.getMessage());}}});}}});}
 private final Runnable tick=new Runnable(){public void run(){if(destroyed)return;CastServer s=CastServer.get();if(s!=null&&!s.closed){status.setText(s.error.isEmpty()?"接收已开启 · "+(s.state.equals("PLAYING")?"正在投屏":s.state.equals("PAUSED_PLAYBACK")?"投屏已暂停":s.state.equals("TRANSITIONING")?"正在连接视频":"等待手机连接"):s.error);detail.setText(s.ip);}ui.postDelayed(this,1500);}};
 protected void onResume(){super.onResume();TvUi.inset(this);ScreenPolicy.applyWindow(this);}
 protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
